local bit = bit or bit32
if not bit then
    bit = {}
    local function check_int(n)
        n = math.floor(n)
        if n < 0 then n = n + 2^32 end
        return n % 2^32
    end
    function bit.band(a, b)
        a, b = check_int(a), check_int(b)
        local r = 0
        local bit_val = 1
        for _ = 1, 32 do
            if a % 2 == 1 and b % 2 == 1 then
                r = r + bit_val
            end
            a = math.floor(a / 2)
            b = math.floor(b / 2)
            bit_val = bit_val * 2
        end
        return r
    end
    function bit.bxor(a, b)
        a, b = check_int(a), check_int(b)
        local r = 0
        local bit_val = 1
        for _ = 1, 32 do
            if a % 2 ~= b % 2 then
                r = r + bit_val
            end
            a = math.floor(a / 2)
            b = math.floor(b / 2)
            bit_val = bit_val * 2
        end
        return r
    end
    function bit.rshift(a, n)
        return math.floor(check_int(a) / (2 ^ n))
    end
end

